def read_document(records, principal, document_id):
    record = records[document_id]
    if principal is None or record['tenant_id'] != principal['tenant_id'] or record['owner_id'] != principal['user_id']:
        raise PermissionError('denied')
    return record['body']

from pathlib import Path
def read_file(root, name):
    return (Path(root) / name).read_text()

from pathlib import Path
def read_file(root, name):
    base = Path(root).resolve(strict=True)
    path = (base / name).resolve(strict=True)
    if not path.is_relative_to(base):
        raise PermissionError('denied')
    return path.read_text()

def fetch_status(client, target):
    destinations = {'status': 'https://catalog.example.test/v1/status'}
    if target not in destinations:
        raise PermissionError('denied')
    response = client.get(destinations[target], follow_redirects=False)
    if response.status_code != 200:
        raise ValueError('unexpected upstream status')
    return response.text
